<script setup lang="ts">const route=useRoute(),config=useRuntimeConfig(),{api,media}=useShopApi(),{add}=useCart(),{addRecent}=useRecentlyViewed();const{data:p}=await useAsyncData(`product-${route.params.slug}`,()=>api<any>(`/catalog/products/${route.params.slug}`));const selected=ref(0),variant=ref(0),adding=ref(false),money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v);const description=computed(()=>p.value?.seo?.description||p.value?.short_description||p.value?.title),image=computed(()=>p.value?.media?.[0]?media(p.value.media[0].path):undefined);useSeoMeta(()=>({title:p.value?.seo?.title||p.value?.title||'محصول',description:description.value,ogTitle:p.value?.title,ogDescription:description.value,ogImage:image.value,ogType:'website',twitterCard:'summary_large_image'}));useHead(()=>({link:[{rel:'canonical',href:`${String(config.public.siteUrl).replace(/\/$/,'')}/products/${route.params.slug}`}],script:[{type:'application/ld+json',children:JSON.stringify({'@context':'https://schema.org','@type':'Product',name:p.value?.title,description:description.value,image:p.value?.media?.map((m:any)=>media(m.path))||[],sku:p.value?.variants?.[0]?.sku,brand:{'@type':'Brand',name:p.value?.brand?.title||'بدون برند'},offers:{'@type':'AggregateOffer',priceCurrency:'IRR',lowPrice:Math.min(...(p.value?.variants?.map((v:any)=>v.price*10)||[0])),highPrice:Math.max(...(p.value?.variants?.map((v:any)=>v.price*10)||[0])),offerCount:p.value?.variants?.length||0,availability:p.value?.variants?.some((v:any)=>v.stock>0)?'https://schema.org/InStock':'https://schema.org/OutOfStock'}})}]}));onMounted(()=>{if(p.value)addRecent(p.value)});async function addToCart(){adding.value=true;try{await add(p.value.variants[variant.value].id)}finally{adding.value=false}}</script>
<template><div v-if="p" class="mx-auto max-w-7xl px-4 py-8"><p class="mb-5 text-sm text-slate-400">خانه / {{p.category?.title}} / {{p.title}}</p><div class="grid gap-10 lg:grid-cols-2"><section><div class="aspect-square overflow-hidden rounded-3xl bg-stone-100"><img v-if="p.media?.[selected]" :src="media(p.media[selected].path)" class="size-full object-cover"><div v-else class="grid size-full place-items-center text-8xl text-stone-300">◇</div></div><div class="mt-3 flex gap-3 overflow-auto"><button v-for="(m,i) in p.media" :key="m.id" :class="['size-20 shrink-0 overflow-hidden rounded-xl border-2',selected===i?'border-brand-700':'border-transparent']" @click="selected=i"><img :src="media(m.path)" class="size-full object-cover"></button></div></section><section class="py-3"><span class="rounded-lg bg-brand-50 px-3 py-1 text-xs font-bold text-brand-700">{{p.brand?.title||'اثر دست‌ساز'}}</span><h1 class="mt-5 text-3xl font-black leading-tight">{{p.title}}</h1><p class="mt-5 text-sm leading-8 text-slate-500">{{p.short_description}}</p><div class="my-7 border-y py-6"><p class="mb-3 text-sm font-bold">انتخاب تنوع</p><div class="flex flex-wrap gap-2"><button v-for="(v,i) in p.variants" :key="v.id" :disabled="!v.stock" :class="['rounded-xl border px-4 py-3 text-sm',variant===i?'border-brand-700 bg-brand-50 text-brand-700':'bg-white',!v.stock&&'opacity-40']" @click="variant=i">{{Object.values(v.attributes||{}).filter(Boolean).join(' / ')||v.sku}}</button></div></div><div class="rounded-2xl border bg-white p-5 shadow-soft"><div class="flex items-end justify-between"><span class="text-sm text-slate-500">قیمت محصول</span><div class="text-left"><del v-if="p.variants[variant]?.compare_at_price" class="text-sm text-slate-400">{{money(p.variants[variant].compare_at_price)}}</del><p class="text-2xl font-black text-brand-900">{{money(p.variants[variant]?.price)}} <span class="text-sm">تومان</span></p></div></div><button :disabled="adding||!p.variants[variant]?.stock" class="mt-5 w-full rounded-xl bg-brand-700 py-4 font-black text-white disabled:bg-slate-300" @click="addToCart">{{adding?'در حال افزودن…':p.variants[variant]?.stock?'افزودن به سبد خرید':'ناموجود'}}</button><div class="mt-4 flex justify-around text-xs text-slate-400"><span>✓ ضمانت اصالت</span><span>✓ ارسال امن</span><span>✓ پشتیبانی خرید</span></div></div></section></div><section class="mt-14 rounded-3xl border bg-white p-6 md:p-10"><h2 class="text-xl font-black">معرفی و مشخصات</h2><div class="mt-5 whitespace-pre-line text-sm leading-9 text-slate-600">{{p.description}}</div></section></div></template>
